package com.namazteam.lux;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import org.json.*;import java.util.*;import java.text.*;
public class PrayerReceiver extends BroadcastReceiver {
 static String[] names={"İmsak","Güneş","Öğle","İkindi","Akşam","Yatsı"};
 public static void channel(Context c){NotificationChannel ch=new NotificationChannel("prayer","Namaz vakti hatırlatmaları",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Diyanet vakitlerine göre namaz hatırlatmaları. Ezan kaydı içermez.");ch.enableVibration(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}
 static PendingIntent pending(Context c,int id,String title,String text){Intent i=new Intent(c,PrayerReceiver.class).putExtra("title",title).putExtra("text",text);return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static synchronized void schedule(Context c){try{android.content.SharedPreferences p=c.getSharedPreferences("lux",0);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);int old=p.getInt("scheduled",0);for(int i=0;i<old;i++)am.cancel(pending(c,i,"",""));JSONObject cfg=new JSONObject(p.getString("settings","{}"));if(!cfg.optBoolean("enabled",false)){p.edit().putInt("scheduled",0).apply();return;}JSONObject data=new JSONObject(p.getString("data","{}"));JSONArray days=data.optJSONArray("days");if(days==null)return;String city=data.optString("city");JSONArray on=cfg.optJSONArray("prayers");int offset=Math.max(0,Math.min(60,cfg.optInt("offset",0))),count=0;SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setTimeZone(TimeZone.getTimeZone("Europe/Istanbul"));f.setLenient(false);for(int d=0;d<days.length()&&count<400;d++){JSONObject day=days.getJSONObject(d);JSONArray times=day.getJSONArray("times");for(int i=0;i<6;i++){if(on!=null&&!on.optBoolean(i,false))continue;long at=f.parse(day.getString("date")+" "+times.getString(i)).getTime()-offset*60000L;if(at<System.currentTimeMillis()+1000)continue;String title=offset>0?names[i]+" vaktine "+offset+" dakika":names[i]+" vakti";PendingIntent pi=pending(c,count++,title,city+" • "+times.getString(i)+" • Diyanet");if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}}p.edit().putInt("scheduled",count).apply();}catch(Exception e){c.getSharedPreferences("lux",0).edit().putInt("scheduled",0).apply();}}
 public static void show(Context c,String title,String text){channel(c);try{PendingIntent open=PendingIntent.getActivity(c,1,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(c,"prayer").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(title).setContentText(text).setColor(Color.rgb(205,169,91)).setContentIntent(open).setAutoCancel(true).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),n);}catch(SecurityException e){}}
 public void onReceive(Context c,Intent i){show(c,i.getStringExtra("title"),i.getStringExtra("text"));}
}
